  border: 1px solid #ddd6fe;
  border-radius: 999px;
  background: var(--purple-50);
  color: var(--purple-800);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

