.art-title {
  margin: 0 0 0.9rem;
  color: var(--ink-strong);
  font-size: 1.45rem;
  font-weight: 850;
  line-height: 1.15;
}

.art-list {
  display: grid;
  gap: 0.6rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.art-list li {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.55rem 0.6rem;
  border: 1px solid #ede9fe;
  border-radius: 0.75rem;
  background: #fdfcff;
  color: #374151;
  font-size: 0.84rem;
  line-height: 1.35;
}

.art-list strong {
  display: block;
  color: var(--purple-800);
  font-size: 0.78rem;
}

.art-swatch {
  flex: none;
  width: 0.55rem;
  height: 2rem;
  border-radius: 999px;
}

.art-purple {
  background: var(--purple-600);
}

.art-teal {
  background: var(--teal-700);
}

.art-pink {
  background: var(--pink-700);
}

/* --------------------------------------------------------------------------
   Course cards
   -------------------------------------------------------------------------- */

.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 17rem), 1fr));
  gap: 1.25rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.course-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 1.15rem;
  border: 1px solid var(--line);
  border-top: 6px solid var(--dept-color, var(--purple-600));
  border-radius: var(--radius-md);
  background: #ffffff;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 160ms ease, transform 160ms ease;
}

.course-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.course-card:focus-within {
  box-shadow: var(--shadow-md);
}

.dept-computer-science {
  --dept-color: #6d28d9;
  --dept-bg: #ede9fe;
  --dept-ink: #4c1d95;
}

.dept-mathematics {
  --dept-color: #1d4ed8;
  --dept-bg: #dbeafe;
  --dept-ink: #1e3a8a;
}

.dept-physics {
  --dept-color: #0e7490;
  --dept-bg: #cffafe;
  --dept-ink: #155e75;
}

.dept-biology {
  --dept-color: #15803d;
  --dept-bg: #dcfce7;
  --dept-ink: #14532d;
}

.dept-business {
  --dept-color: #c2410c;
  --dept-bg: #ffedd5;
  --dept-ink: #7c2d12;
}

.dept-psychology {
  --dept-color: #be185d;
  --dept-bg: #fce7f3;
  --dept-ink: #831843;
}

.dept-art-design {
  --dept-color: #a21caf;
  --dept-bg: #fae8ff;
  --dept-ink: #701a75;
}

.dept-english {
  --dept-color: #b45309;
  --dept-bg: #fef3c7;
  --dept-ink: #78350f;
}

.card-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-bottom: 0.8rem;
}

.course-card h3 {
  margin-bottom: 0.5rem;
  font-size: 1.15rem;
}

.course-code {
  display: block;
  margin-bottom: 0.15rem;
  color: var(--dept-ink, var(--purple-800));
  font-size: 0.78rem;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.course-title {
  display: block;
}

.course-desc {
  margin-bottom: 1rem;
  color: var(--muted);
  font-size: 0.94rem;
}

.course-meta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem 0.9rem;
  margin: 0 0 1rem;
  font-size: 0.84rem;
}

.course-meta div {
  min-width: 0;
}

.course-meta dt {
  color: #374151;
  font-size: 0.7rem;
  font-weight: 850;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.course-meta dd {
  margin: 0;
  color: #374151;
}

.card-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.7rem;
  margin-top: auto;
  padding-top: 0.9rem;
  border-top: 1px dashed var(--line);
}

.seats {
  color: #374151;
  font-size: 0.84rem;
  font-weight: 700;
}

.card-footer .btn {
  margin-left: auto;
}

/* --------------------------------------------------------------------------
   Steps and call to action
   -------------------------------------------------------------------------- */

.steps {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));
  gap: 1.2rem;
  margin: 0;
  padding: 0;
  list-style: none;
  counter-reset: step;
}

.steps li {
  padding: 1.3rem;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: #ffffff;
  box-shadow: var(--shadow-sm);
}

.steps li::before {
  display: grid;
  place-items: center;
  width: 2.3rem;
  height: 2.3rem;
  margin-bottom: 0.8rem;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--purple-600), var(--teal-700));
  color: #ffffff;
  font-weight: 900;
  counter-increment: step;
  content: counter(step);
}

.steps h3 {
  margin-bottom: 0.35rem;
}

.steps p {
  margin-bottom: 0;
  color: var(--muted);
}

.cta-panel {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1.5rem;
  padding: clamp(1.5rem, 4vw, 2.6rem);
  border-radius: var(--radius-lg);
  background:
    radial-gradient(circle at 85% 15%, rgba(94, 234, 212, 0.35), transparent 30%),
    linear-gradient(120deg, var(--purple-950), var(--teal-900));
  box-shadow: var(--shadow-md);
}

.cta-panel h2 {
  margin-bottom: 0.4rem;
  color: #ffffff;
}

.cta-panel p {
  max-width: 56ch;
  margin-bottom: 0;
  color: #e0e7ff;
}

.cta-panel .eyebrow {
  border-color: rgba(255, 255, 255, 0.35);
  background: rgba(255, 255, 255, 0.12);
  color: #fde68a;
}

/* --------------------------------------------------------------------------
   Page intro, catalog filters and empty states
   -------------------------------------------------------------------------- */

.page-intro {
  border-bottom: 1px solid #e9d5ff;
  background:
    radial-gradient(circle at 85% 10%, rgba(204, 251, 241, 0.9), transparent 38%),
    radial-gradient(circle at 12% 90%, rgba(251, 207, 232, 0.65), transparent 34%),
    linear-gradient(120deg, #faf5ff, #eff6ff 58%, #f0fdfa);
  padding-block: clamp(2rem, 5vw, 3.5rem);
}

.page-intro h1 {
  max-width: 20ch;
}

.page-intro p:last-child {
  margin-bottom: 0;
}

.filter-bar {
  display: grid;
  grid-template-columns: minmax(220px, 2fr) repeat(3, minmax(140px, 1fr)) auto;
  align-items: end;
  gap: 1rem;
  padding: 1.25rem;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: #ffffff;
  box-shadow: var(--shadow-sm);
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  min-width: 0;
}

.field label,
.field-label {
  color: var(--ink);
  font-size: 0.9rem;
  font-weight: 750;
}

.req {
  color: var(--muted);
  font-size: 0.85em;
  font-weight: 600;
}

.hint {
  margin: 0.15rem 0 0;
  color: var(--muted);
  font-size: 0.85rem;
}

input,
select,
textarea {
  width: 100%;
  min-height: 44px;
  padding: 0.6rem 0.72rem;
  border: 2px solid #6b7280;
  border-radius: var(--radius-sm);
  background: #ffffff;
  color: var(--ink-strong);
  font-size: 1rem;
}

input::placeholder {
  color: var(--muted);
  opacity: 1;
}

input:hover,
select:hover,
textarea:hover {
  border-color: #374151;
}

input[aria-invalid="true"],
select[aria-invalid="true"],
textarea[aria-invalid="true"] {
  border-color: var(--red-700);
  background: #fff8f8;
}

select {
  padding-right: 2.6rem;
  background-image:
    linear-gradient(45deg, transparent 50%, #374151 50%),
    linear-gradient(135deg, #374151 50%, transparent 50%);
  background-position:
    calc(100% - 1.2rem) 50%,
    calc(100% - 0.85rem) 50%;
  background-size: 0.36rem 0.36rem, 0.36rem 0.36rem;
  background-repeat: no-repeat;
  appearance: none;
}

textarea {
  min-height: 7rem;
  resize: vertical;
}

.field-error {
  display: flex;
  align-items: flex-start;
  gap: 0.4rem;
  margin: 0.2rem 0 0;
  color: var(--red-800);
  font-size: 0.9rem;
  font-weight: 750;
}

.field-error::before {
  content: "!";
  display: grid;
  place-items: center;
  flex: none;
  width: 1.1rem;
  height: 1.1rem;
  margin-top: 0.08rem;
  border-radius: 50%;
  background: var(--red-800);
  color: #ffffff;
  font-size: 0.72rem;
  font-weight: 900;
}

.empty-state {
  padding: clamp(2rem, 5vw, 3rem) 1rem;
  border: 2px dashed #c4b5fd;
  border-radius: 20px;
  background: var(--purple-50);
  text-align: center;
}

.empty-state h3 {
  margin-bottom: 0.35rem;
}

.empty-state p {
  max-width: 48ch;
  margin-inline: auto;
  color: var(--muted);
}

/* --------------------------------------------------------------------------
   Form pages
   -------------------------------------------------------------------------- */

.split-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(0, 0.8fr);
  align-items: start;
  gap: 1.5rem;
}

.form-card,
.info-card,
.summary-card {
  padding: clamp(1.25rem, 3vw, 2rem);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: #ffffff;
  box-shadow: var(--shadow-sm);
}

.form-card {
  border-top: 6px solid var(--purple-600);
}

.info-card {
  border-top: 6px solid var(--teal-700);
  background: linear-gradient(180deg, var(--teal-50), #ffffff 45%);
}

.summary-card {
  border-top: 6px solid var(--pink-700);
  background: linear-gradient(180deg, #fff1f7, #ffffff 55%);
}

.form-intro {
  max-width: 62ch;
  color: var(--muted);
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.field-full {
  grid-column: 1 / -1;
}

.form-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.9rem;
  margin-top: 1.4rem;
  padding-top: 1.2rem;
  border-top: 1px solid var(--line);
}

.error-summary {
  margin: 0 0 1.3rem;
  padding: 1rem 1.15rem;
  border: 2px solid var(--red-700);
  border-radius: var(--radius-sm);
  background: #fef2f2;
  color: var(--red-800);
}

.error-summary h3 {
  margin-bottom: 0.4rem;
  color: var(--red-800);
  font-size: 1.05rem;
}

.error-summary ul {
  margin: 0;
  padding-left: 1.25rem;
}

.error-summary a {
  color: var(--red-800);
  font-weight: 750;
}

.info-card h2,
.summary-card h2 {
  margin-bottom: 0.75rem;
}

.check-list {
  display: grid;
  gap: 0.65rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.check-list li {
  position: relative;
  padding-left: 1.7rem;
  color: #374151;
}

.check-list li::before {
  content: "✓";
  position: absolute;
  top: 0.08rem;
  left: 0;
  display: grid;
  place-items: center;
  width: 1.2rem;
  height: 1.2rem;
  border-radius: 50%;
  background: var(--teal-100);
  color: var(--teal-800);
  font-size: 0.75rem;
  font-weight: 900;
}

.summary-list {
  display: grid;
  gap: 0.8rem;
  margin: 0 0 1.3rem;
}

.summary-list div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  padding-bottom: 0.8rem;
  border-bottom: 1px dashed #fbcfe8;
}

.summary-list div:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.summary-list dt {
  color: var(--muted);
  font-weight: 650;
}

.summary-list dd {
  margin: 0;
  color: var(--ink-strong);
  font-size: 1.35rem;
  font-weight: 850;
}

/* --------------------------------------------------------------------------
   Registered courses table
   -------------------------------------------------------------------------- */

.table-wrap {
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: #ffffff;
  box-shadow: var(--shadow-sm);
}

.table-wrap:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

table {
  width: 100%;
  min-width: 46rem;
  border-collapse: collapse;
}

caption {
  padding: 1rem 1.15rem 0.35rem;
  color: var(--ink-strong);
  font-weight: 800;
  text-align: left;
}

thead th {
  padding: 0.75rem 1rem;
  border-bottom: 2px solid #ddd6fe;
  background: var(--purple-50);
  color: #374151;
  font-size: 0.76rem;
  font-weight: 850;
  letter-spacing: 0.06em;
  text-align: left;
  text-transform: uppercase;
}

tbody th,
tbody td {
  padding: 0.9rem 1rem;
  border-bottom: 1px solid var(--line);
  color: #374151;
  text-align: left;
  vertical-align: top;
}

tbody tr:last-child th,
tbody tr:last-child td {
  border-bottom: 0;
}

tbody tr:hover {
  background: #fdfcff;
}

tbody th {
  font-weight: 700;
}

.table-code {
  display: block;
  color: var(--purple-800);
  font-weight: 850;
}

.table-title {
  display: block;
  color: #374151;
  font-size: 0.88rem;
  font-weight: 550;
}

/* --------------------------------------------------------------------------
   Confirmation dialog
   -------------------------------------------------------------------------- */

.modal {
  width: min(100% - 2rem, 32rem);
  max-height: calc(100dvh - 2rem);
  padding: 0;
  border: 0;
  border-radius: var(--radius-lg);
  background: transparent;
  color: var(--ink);
  overflow: auto;
}

.modal::backdrop {
  background: rgba(17, 24, 39, 0.62);
}

.modal-card {
  padding: clamp(1.25rem, 4vw, 2rem);
  border-top: 8px solid var(--purple-600);
  border-radius: var(--radius-lg);
  background: #ffffff;
  box-shadow: 0 28px 70px rgba(17, 24, 39, 0.35);
}

.modal-icon {
  display: grid;
  place-items: center;
  width: 3rem;
  height: 3rem;
  margin-bottom: 1rem;
  border-radius: 50%;
  background: var(--purple-100);
  color: var(--purple-800);
  font-size: 1.45rem;
  font-weight: 900;
}

.modal h2 {
  margin-bottom: 0.5rem;
  font-size: 1.55rem;
}

.modal p {
  color: var(--muted);
}

.modal-details {
  display: grid;
  gap: 0.65rem;
  margin: 1.2rem 0 1.5rem;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-soft);
}

.modal-details div {
  display: grid;
  grid-template-columns: 7rem minmax(0, 1fr);
  gap: 0.75rem;
}

.modal-details dt {
  color: #374151;
  font-size: 0.85rem;
  font-weight: 850;
}

.modal-details dd {
  margin: 0;
  color: var(--ink-strong);
}

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.75rem;
}

/* --------------------------------------------------------------------------
   Footer
   -------------------------------------------------------------------------- */

.site-footer {
  margin-top: 3rem;
  padding: 2.6rem 0 1.5rem;
  background:
    radial-gradient(circle at 85% 10%, rgba(15, 118, 110, 0.55), transparent 35%),
    linear-gradient(120deg, var(--purple-950), var(--teal-900));
  color: #f8fafc;
}

.footer-inner {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 2rem;
}

.footer-brand {
  margin-bottom: 0.4rem;
  color: #ffffff;
  font-size: 1.1rem;
  font-weight: 850;
}

.site-footer p {
  margin-bottom: 0.45rem;
  color: #e0e7ff;
}

.footer-heading {
  margin-bottom: 0.5rem;
  color: #ffffff;
  font-size: 1.02rem;
}

.site-footer a {
  display: inline-block;
  padding: 0.2rem 0;
  color: var(--focus-on-dark);
  font-weight: 700;
}

.site-footer a:hover {
  color: #ffffff;
}

.site-footer a:focus-visible {
  outline-color: var(--focus-on-dark);
}

.copyright {
  width: min(100% - 2rem, var(--max-width));
  margin: 2rem auto 0;
  padding-top: 1rem;
  border-top: 1px solid rgba(255, 255, 255, 0.24);
  color: #e0e7ff;
  font-size: 0.85rem;
}

/* --------------------------------------------------------------------------
   Responsive adjustments
   -------------------------------------------------------------------------- */

@media (max-width: 1050px) {
  .filter-bar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .field-search {
    grid-column: 1 / -1;
  }

  #clear-filters {
    justify-self: start;
  }
}

@media (max-width: 900px) {
  .split-layout {
    grid-template-columns: 1fr;
  }

  .hero-grid {
    grid-template-columns: 1fr;
  }

  .hero-copy h1 {
    max-width: 18ch;
  }

  .hero-art {
    order: 2;
  }
}

@media (max-width: 820px) {
  .nav-toggle {
    display: inline-flex;
  }

  .primary-nav {
    flex-basis: 100%;
    margin-left: 0;
  }

  .nav-list {
    display: none;
    flex-direction: column;
    align-items: stretch;
    gap: 0.15rem;
    padding: 0.4rem 0 0.2rem;
  }

  .nav-list.is-open {
    display: flex;
  }

  .nav-list a {
    border-radius: 0.75rem;
  }
}

@media (max-width: 600px) {
  .form-grid {
    grid-template-columns: 1fr;
  }

  .field-full {
    grid-column: auto;
  }

  .filter-bar {
    grid-template-columns: 1fr;
  }

  .field-search {
    grid-column: auto;
  }

  .course-meta {
    grid-template-columns: 1fr;
  }

  .modal-details div {
    grid-template-columns: 1fr;
    gap: 0.1rem;
  }

  .modal-actions .btn {
    flex: 1 1 100%;
  }

  .card-footer .btn {
    width: 100%;
    margin-left: 0;
  }

  .summary-list div {
    align-items: flex-start;
    flex-direction: column;
    gap: 0.15rem;
  }
}

@media (max-width: 380px) {
  .brand-text {
    font-size: 0.94rem;
  }

  .brand-mark {
    width: 2.3rem;
    height: 2.3rem;
  }

  .btn {
    padding-inline: 0.9rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

input.newString:
.error-summary:focus {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.error-summary ul {
  margin: 0;
  padding-left: 1.25rem;
}

