node --check js/app.js && node --check js/data.js && python3 - <<'PY'
from html.parser import HTMLParser
from pathlib import Path

VOID = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
class Checker(HTMLParser):
    def __init__(self, path):
        super().__init__(convert_charrefs=True)
        self.path=path; self.stack=[]; self.errors=[]
    def handle_starttag(self, tag, attrs):
        if tag not in VOID:
            self.stack.append((tag, self.getpos()))
    def handle_endtag(self, tag):
        if tag in VOID: return
        if not self.stack:
            self.errors.append(f'{self.path}:{self.getpos()[0]}: stray </{tag}>')
            return
        if self.stack[-1][0]==tag:
            self.stack.pop()
        else:
            # find in stack
            idx=None
            for i in range(len(self.stack)-1,-1,-1):
                if self.stack[i][0]==tag:
                    idx=i; break
            if idx is None:
                self.errors.append(f'{self.path}:{self.getpos()[0]}: unexpected </{tag}>')
            else:
                for t,pos in self.stack[idx+1:]:
                    self.errors.append(f'{self.path}:{pos[0]}: <{t}> not closed before </{tag}>')
                del self.stack[idx:]

for p in sorted(Path('.').glob('*.html')):
    c=Checker(str(p))
    c.feed(p.read_text())
    for t,pos in c.stack:
        c.errors.append(f'{p}:{pos[0]}: <{t}> never closed')
    if c.errors:
        print('\n'.join(c.errors))
    else:
        print(f'{p}: nesting OK')
