const { JSDOM, VirtualConsole } = require('jsdom');

const base = 'http://127.0.0.1:8765/';
const results = [];
let failures = 0;

function check(name, condition, detail) {
  if (condition) {
    results.push('PASS ' + name);
  } else {
    failures++;
    results.push('FAIL ' + name + (detail ? ' :: ' + detail : ''));
  }
}

function wait(ms) { return new Promise(r => setTimeout(r, ms)); }

async function loadPage(page) {
  const errors = [];
  const vc = new VirtualConsole();
  vc.on('jsdomError', e => errors.push('jsdomError: ' + e.message));
  vc.on('error', (...args) => errors.push('console.error: ' + args.join(' ')));
  vc.on('warn', (...args) => errors.push('console.warn: ' + args.join(' ')));
  const dom = await JSDOM.fromURL(base + page, {
    runScripts: 'dangerously',
    resources: 'usable',
    pretendToBeVisual: true,
    virtualConsole: vc,
    beforeParse(window) {
      window.matchMedia = window.matchMedia || function (query) {
        return {
          matches: false,
          media: query,
          onchange: null,
          addEventListener() {},
          removeEventListener() {},
          addListener() {},
          removeListener() {},
          dispatchEvent() { return false; }
        };
      };
      const proto = window.HTMLDialogElement ? window.HTMLDialogElement.prototype : window.HTMLElement.prototype;
      proto.showModal = function () {
        this.setAttribute('open', '');
        this.dispatchEvent(new window.Event('open'));
      };
      proto.close = function () {
        this.removeAttribute('open');
        this.dispatchEvent(new window.Event('close'));
      };
    }
  });
  await new Promise(resolve => dom.window.addEventListener('load', resolve));
  await wait(150);
  return { dom, errors };
}

function fire(el, type, opts) {
  el.dispatchEvent(new el.ownerDocument.defaultView.Event(type, Object.assign({ bubbles: true }, opts)));
}

